  [F('أكبر حيوان', 'الحوت الأزرق أكبر حيوان عُرف على الأرض حتى اليوم.', '1f40b', 1),
   F('الأخطبوط', 'للأخطبوط ثلاثة قلوب وثماني أذرع.', '1f419', 3),
   F('الدلفين', 'الدلفين حيوان ثديي يتنفس الهواء، وليس سمكة.', '1f42c', 2),
   F('سلاحف عُمان', 'تضع السلاحف الخضراء بيضها على شواطئ في سلطنة عُمان، ومنها شاطئ رأس الجِنز.', '1f422', 3)],
  [V('خياشيم', 'أعضاء تتنفس بها الأسماك تحت الماء', 2), V('ثديي', 'حيوان يرضع صغيره الحليب', 3), V('محيط', 'مساحة ماء مالح واسعة جدًا', 2), V('درع', 'غطاء صلب يحمي السلحفاة', 2), V('شاطئ', 'حافة اليابسة عند البحر', 1)],
